fn merge_runs(left: &[u32], right: &[u32]) -> Vec<u32> {
    let mut buf = Vec::with_capacity(left.len() + right.len());
    let (mut i, mut j) = (0usize, 0usize);
    while i < left.len() && j < right.len() {
        if left[i] <= right[j] {
            buf.push(left[i]);
            i += 1;
        } else {
            buf.push(right[j]);
            j += 1;
        }
    }
    while i < left.len() {
        buf.push(left[i]);
        i += 1;
    }
    while j < right.len() {
        buf.push(right[j]);
        j += 1;
    }
    buf
}
